// Round 2 hybrid (D), with the three earlier disposable layouts retained for comparison.
// Mock state only. No game engine, requests, credentials, persistence or production build.
const variants=['A','B','C','D'];
const names={A:'冒险优先',B:'角色工作台',C:'紧凑总览',D:'A＋B 组合'};
const params=new URLSearchParams(location.search);
let variant=variants.includes(params.get('variant'))?params.get('variant'):'D';
const initial=()=>({page:params.get('view')==='report'?'report':'adventure',char:0,tab:'equipment',selected:[0,1,2,3,4],remember:true,remembered:[0,1,2,3,4],stamina:12,reserved:0,money:24800,battle:'idle',simulation:'idle',occupied:[],report:'formal',event:0,gear:0,candidate:1,gearSlot:'weapon',gearQuery:'',learned:false,points:8,acceptedConfigs:{formal:[],sim:[]},
  chars:[['阿岚','战士','mon_079.gif','前排'],['梨央','巫师','mon_018.gif','后排'],['白露','牧师','mon_213.gif','后排'],['林间','猎人','mon_219rr.gif','后排'],['影','刺客','mon_216y.gif','前排'],['远山','战士','mon_079.gif','前排'],['星灯','巫师','mon_018.gif','后排'],['青禾','牧师','mon_213.gif','后排']],
  plans:Array.from({length:8},()=>{const rules=[{kind:'self',value:50,extra:true,action:'防御'},{kind:'always',value:0,extra:false,action:'普通攻击'},{kind:'self',value:25,extra:false,action:'防御'}];return {rules,savedRules:structuredClone(rules),backup:[{kind:'always',value:0,extra:false,action:'防御'}],dirty:false,save:'已保存',capacity:4}})});
let state=initial();
const draft=()=>state.plans[state.char];
// Fixed historical sample: editing today's party never rewrites an old report.
const reportParty=initial().chars.slice(0,5).map(c=>[...c]);
const savedBattleRules=i=>{let rows=0;return state.plans[i].savedRules.filter(r=>{rows+=r.extra?2:1;return rows<=state.plans[i].capacity})};
const gear=[{name:'短剑',refine:'+0',id:'样品 01',atk:10,load:1,img:'we_sword026.png',allowed:true},{name:'短剑',refine:'+1',id:'样品 02',atk:12,load:1,img:'we_sword026.png',allowed:true},{name:'战戟',refine:'+0',id:'样品 03',atk:21,load:4,img:'we_spear016.png',allowed:false}];
gear.forEach(g=>g.slot='weapon');
gear.push(...Array.from({length:10},(_,i)=>({name:'短剑',refine:i%2?'+1':'+0',id:`样品 ${String(i+4).padStart(2,'0')}`,atk:i%2?12:10,load:1,img:'we_sword026.png',allowed:true,slot:'weapon'})));
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gearCandidates=()=>gear.map((g,i)=>({g,i})).filter(({g,i})=>i!==state.gear&&g.slot===state.gearSlot&&(g.name+g.id).includes(state.gearQuery));
const btn=(text,action,extra='')=>`<button data-action="${action}" ${extra}>${text}</button>`;
const sprite=(file,alt='',cls='sprite')=>`<img class="${cls}" src="assets/${file}" alt="${alt}">`;
const notice=text=>{const n=document.querySelector('#notice');n.textContent=text;n.className='visible';clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.className='',4500)};
const pending=x=>['pending','unknown','manual'].includes(x);
const busy=()=>pending(state.battle);
const occupied=(i=state.char)=>busy()&&state.occupied.includes(i);
const scenario=()=>document.querySelector('#scenario').value;
function header(){return `<header><div class="row spread"><div><div class="brand">HOF REDUX</div><small>风行旅团 · 模拟账号</small></div><span class="tag">UI 原型</span></div><div class="wallet"><span>金钱 <b>${state.money.toLocaleString()}</b></span><span>体力可用 <b>${state.stamina-state.reserved}</b> / 总量 ${state.stamina}</span>${state.reserved?`<span>预留 ${state.reserved}</span>`:''}</div></header>`}
function nav(){if(variant==='D')return `<nav class="bottomnav" aria-label="主要功能">${[['adventure','冒险'],['character','角色'],['report','战报'],['town','城镇']].map(([p,n])=>btn(n,'page',`data-page="${p}" class="${(state.page==='party'?'character':state.page)===p?'active':''}"`)).join('')}</nav>`;return `<nav class="bottomnav" aria-label="主要功能">${[['adventure','冒险'],['party','角色'],['report','战报'],['town','城镇']].map(([p,n])=>btn(n,'page',`data-page="${p}" class="${state.page===p?'active':''}"`)).join('')}</nav>`}
function status(){
  const messages={pending:'已受理，正在处理。离开页面后仍会继续。',unknown:'未收到响应，正在核对这次操作；请勿重复发起。',manual:'等待管理员处理，原操作保留。',cancelled:'已故障取消，预留和占用已释放，未扣体力、未发收益。受理时保存的配置或记忆仍保留。'};
  return [['formal',state.battle,'正式战'],['sim',state.simulation,'模拟战']].filter(([,value])=>messages[value]).map(([mode,value,name])=>`<div class="card warning"><b>${name}：${messages[value]}</b><p class="muted">这是同一笔操作的状态，不代表收益已到账。</p><details><summary>查看本次固定的已保存战术（模拟）</summary><p class="muted">仅展示本次有效规则；之后修改草稿或保存新配置，不改变此处快照。</p>${state.acceptedConfigs[mode].map(config=>`<section><h3>${config.name}</h3>${config.rules.length?`<ol>${config.rules.map(rule=>`<li>${rule.kind==='self'?`自身 HP ≤ ${rule.value}%`:'无条件'}${rule.extra?' 且自身 SP ≥ 25%':''} → ${rule.action}</li>`).join('')}</ol>`:'<p>无有效规则，将按待机处理。</p>'}</section>`).join('')}</details>${value==='cancelled'?'':btn(value==='unknown'?'查询原操作':'刷新处理状态','resolve',`data-mode="${mode}"`)}<p class="muted">原型：按钮推进模拟状态；预置战报不由这些规则计算。</p></div>`).join('');
}
function adventure(){return `<div class="eyebrow">Adventure</div><h1>出发之前</h1>${status()}<div class="stack"><div class="card"><span class="tag">普通冒险</span><h2>哥布林之森</h2><p>已选 ${state.selected.length} 人 · 本次消耗 1 体力</p><div class="row">${sprite('mon_053.gif','持斧哥布林')}${sprite('mon_121.gif','小蝙蝠')}<span class="muted">敌人示意，不预先确定本场遭遇</span></div><p class="muted">地图名称与预览仅为布局样例。</p>${btn('查看出战成员','page','data-page="party"')}</div><div class="card"><h3>准备状态</h3>${state.selected.some(i=>state.plans[i].dirty)?'<p class="help warning">所选角色有未保存战术。本次出战或团队模拟使用已保存配置；草稿仍保留。</p>':''}<p>${state.selected.map(i=>state.chars[i][0]).join('、')||'尚未选择成员'}</p><label><input type="checkbox" data-field="remember" ${state.remember?'checked':''}>受理成功后记住这些成员</label><p class="muted">不保存装备或战术快照；当前记忆 ${state.remembered.length} 人。</p><div class="actionbar">${btn('确认出战 · 1 体力','battle',`class="primary" ${busy()?'disabled':''}`)}${btn('团队模拟','simulate')}</div><p class="muted">模拟以镜像队伍试战，不消耗体力，不产生收益。</p></div></div>`}
function party(){return `<div class="eyebrow">Party</div>${variant==='D'?'<p class="muted">角色 / 出战编队</p>':''}<h1>出战成员 <small>${state.selected.length}/5</small></h1><p class="muted">按角色列表顺序出战。前后排设置属于角色，修改后用于下一场。</p><div class="stack">${state.chars.map((c,i)=>`<div class="card"><div class="row"><label><input type="checkbox" aria-label="选择 ${c[0]} 出战" data-member="${i}" ${state.selected.includes(i)?'checked':''}></label>${sprite(c[2])}<div class="grow"><b>${c[0]}</b><div class="muted">${c[1]} · Lv.18（示意）</div></div>${btn('培养','character',`data-char="${i}"`)}</div><div class="row spread"><label>阵位 <select data-position="${i}" ${occupied(i)?'disabled':''}><option ${c[3]==='前排'?'selected':''}>前排</option><option ${c[3]==='后排'?'selected':''}>后排</option></select></label><span class="muted">${occupied(i)?'本场占用中':'下一场生效'}</span></div></div>`).join('')}</div><div class="actionbar">${btn('准备出战','page','data-page="adventure" class="primary"')}</div>`}
function roster(){return `<aside class="roster" aria-label="选择培养角色">${state.chars.map((c,i)=>btn(`${sprite(c[2])}<span>${c[0]}</span>`,'character',`data-char="${i}" aria-pressed="${i===state.char}"`)).join('')}</aside>`}
function character(){const c=state.chars[state.char];return `<div class="row">${sprite(c[2])}<div><h1>${c[0]}</h1><span class="muted">${c[1]} · Lv.18 · ${c[3]}</span></div></div><div class="tabs" aria-label="角色培养">${[['equipment','装备'],['tactics','战术'],['skills','技能']].map(([t,n])=>btn(n,'tab',`data-tab="${t}" aria-pressed="${state.tab===t}"`)).join('')}</div>${state.char!==0&&state.tab!=='tactics'?`<div class="help">本轮仅阿岚支持装备与技能样例；全部角色都可编辑战术、编队和阵位。${btn('切换到阿岚','character','data-char="0"')}</div>`:state.tab==='equipment'?equipment():state.tab==='tactics'?tactics():skills()}`}
function equipment(){
  const current=gear[state.gear],candidates=gearCandidates(),slotCount=gear.filter((g,i)=>i!==state.gear&&g.slot===state.gearSlot).length,selected=candidates.find(({i})=>i===state.candidate)?.g;
  return `<h2>装备比较</h2><div class="grid2"><div class="card">武器<b class="row">${sprite(current.img,'','item-sprite')}${current.name}${current.refine}</b><small>${current.id}</small></div><div class="card">盾 / 甲 / 道具<p class="muted">此示例均为空</p></div></div><form class="gear-filters"><label>装备槽位<select data-field="gear-slot">${[['weapon','武器'],['shield','盾'],['armor','甲'],['item','道具']].map(([id,name])=>`<option value="${id}" ${state.gearSlot===id?'selected':''}>${name}</option>`).join('')}</select></label><label>名称或样品编号<input type="search" data-field="gear-query" value="${escapeText(state.gearQuery)}" placeholder="如：短剑 / 样品 03"></label><p class="muted">找到 ${candidates.length} 件 · 每件独立选择，不能装备的仍显示原因。输入后点“筛选”或按回车应用。</p><button type="submit">筛选</button></form><div class="gear-candidates" aria-label="背包装备候选">${candidates.map(({g,i})=>btn(`${sprite(g.img,'','item-sprite')} <span>${g.name}${g.refine} · ${g.id}${g.allowed?'':'<small class="bad">不可装备：职业不符、承载不足（样例）</small>'}</span>`,'candidate',`data-index="${i}" aria-pressed="${i===state.candidate}"`)).join('')||`<p class="help">${slotCount?'已持有此槽位的装备，但当前搜索没有匹配。请清空或修改名称/样品编号。':'背包中没有此槽位的装备。本轮样例仅包含武器，可切换槽位。'}</p>`}</div>${selected?`<table class="compare"><caption>替换预览（模拟数值）</caption><thead><tr><th>项目</th><th>当前 ${current.id}</th><th>所选 ${selected.id}</th></tr></thead><tbody><tr><td>物理攻击</td><td>${current.atk}</td><td>${selected.atk}（${selected.atk-current.atk>=0?'+':''}${selected.atk-current.atk}）</td></tr><tr><td>承载消耗</td><td>${current.load}</td><td>${selected.load}</td></tr><tr><td>占用槽</td><td>武器</td><td>${selected.allowed?'武器':'武器＋盾'}</td></tr><tr><td>附加效果</td><td>无</td><td>无</td></tr></tbody></table>${selected.allowed?'':'<p class="help warning">当前职业不能使用且承载不足；不会静默卸下其他装备。</p>'}${occupied()?'<p class="help warning">阿岚正在正式出战，当前不能换装；本场结束后再试。</p>':''}<div class="actionbar">${btn(`确认更换为 ${selected.name}${selected.refine} · ${selected.id}`,'equip',`class="primary" ${!selected.allowed||occupied()?'disabled':''}`)}</div>`:''}<p class="muted">替换成功后，旧装备回到背包。正式实现校验职业、占槽、承载、装备实例与占用。</p>`;
}
function activeRules(){let used=0;return draft().rules.map((r,i)=>{const cost=r.extra?2:1;used+=cost;return {r,i,visible:used<=draft().capacity}}).filter(x=>x.visible)}
function tactics(){return `<h2>当前战术</h2><p class="muted">从上到下，执行首个满足条件的规则；没有命中则待机。</p><div class="row spread"><span class="tag">${draft().save}</span>${btn('交换当前 / 备用','swap',occupied()||draft().dirty?'disabled':'')}</div><div class="stack" style="margin-top:12px">${activeRules().map(({r,i})=>`<section class="rule"><b>优先级 ${i+1}</b><label style="width:100%">当<select data-rule="${i}" data-prop="kind"><option value="self" ${r.kind==='self'?'selected':''}>自身 HP 比例 ≤ 阈值</option><option value="always" ${r.kind==='always'?'selected':''}>无条件</option></select></label>${r.kind==='self'?`<label>阈值 <input type="number" min="0" max="100" value="${r.value}" data-rule="${i}" data-prop="value">%</label>`:''}${r.extra?'<div class="condition"><b>且</b> 自身 SP 比例 ≥ 25%<div class="muted">两项条件作为一组移动，共占两行。</div></div>':''}<label style="width:100%">则<select data-rule="${i}" data-prop="action"><option ${r.action==='防御'?'selected':''}>防御</option><option ${r.action==='普通攻击'?'selected':''}>普通攻击</option></select></label><div class="moves">${btn('上移','up',`data-index="${i}" ${i===0?'disabled':''}`)}${btn('下移','down',`data-index="${i}" ${i===activeRules().at(-1).i?'disabled':''}`)}</div></section>`).join('')}</div><div class="actionbar">${btn('保存战术','save',`class="primary" ${occupied()?'disabled':''}`)}${btn('保存并单人测试','test',occupied()?'disabled':'')}${draft().dirty?btn('放弃未保存修改','discard'):''}</div><p class="muted">草稿仅在本页面会话内保留，刷新或关闭可能丢失；出战使用已保存配置。配置保存与测试结果分别显示。修改后请先保存，再交换备用。备用方案共 ${draft().backup.length} 组；交换会保留原当前方案。</p><details><summary>原型场景：战术容量变化</summary><p class="muted">这是模拟控件，不是玩家调节容量的功能。超出容量的完整条件组隐藏，配置仍保留。</p>${btn('模拟容量降低','capacity','data-capacity="1"')}${btn('模拟容量恢复','capacity','data-capacity="4"')}</details>`}
function skills(){return `<h2>技能学习</h2><p>可用技能点 <b>${state.points}</b>（模拟）</p><div class="stack"><div class="card"><h3>防御</h3><span class="tag">已学会</span><p class="muted">已学技能与可学习列表分开显示。</p></div><div class="card"><h3>示例技能 · 用于学习流程</h3><p>条件：当前职业符合 · 等级符合 · 前置技能已学</p><p>需要 4 技能点</p>${btn(state.learned?'已学会':'确认学习 · 消耗 4 点','learn',`${state.learned||occupied()?'disabled':''} class="primary"`)}</div><div class="card"><h3>后续技能示意</h3><p class="muted">尚不可学：等级不足，前置技能未习得。</p><button disabled>条件未满足</button></div></div><p class="help">名称、门槛与点数仅用于验证展示方式，不新增游戏内容。</p>`}
const events=Array.from({length:24},(_,i)=>i===0?'阿岚开始蓄力':i===1?'阿岚使用普通攻击 → 持斧哥布林':i===3?'白露治疗阿岚':i===6?'持斧哥布林死亡':i===9?'暗黑龙召唤随从':i===15?'影死亡':i===23?'本场战斗结束':`${['林间','梨央','小蝙蝠'][i%3]}使用技能 → ${i%2?'敌方':'己方'}单位`);
function units(enemy=false,step=state.event){const list=enemy?[['暗黑龙','mon_013r.gif','前排'],...Array.from({length:6},(_,i)=>[i===5?'召唤随从':i%2?'小蝙蝠':'持斧哥布林',i%2?'mon_121.gif':'mon_053.gif',i<3?'前排':'后排'])]:reportParty.map(c=>[c[0],c[2],c[3]]);return `<div class="formation">${['前排','后排'].map(l=>`<div class="lane"><strong>${l}</strong>${list.map((c,i)=>({c,i})).filter(({c})=>c[2]===l).map(({c,i})=>{const dead=enemy?i===1&&step>=6:i===4&&step>=15;return `<div class="unit ${dead?'dead':''}">${sprite(c[1])}<div class="grow"><b>${c[0]}</b><small style="display:block">${dead?'死亡':`HP ${Math.max(1,100-i*9-step)}/100`}<br>SP ${40-i}/40</small><div class="meter"><span style="width:${dead?0:Math.max(1,100-i*9-step)}%"></span></div></div></div>`}).join('')}</div>`).join('')}</div>`}
function report(){if(variant==='D')return hybridReport();return `<div class="eyebrow">Battle report</div><h1>战报复盘</h1><div class="tabs">${btn('正式战示例','report-type','data-type="formal" aria-pressed="'+(state.report==='formal')+'"')}${btn('模拟战示例','report-type','data-type="sim" aria-pressed="'+(state.report==='sim')+'"')}</div><div class="card"><span class="tag">${state.report==='formal'?'公开 · 保存 90 天':'仅本人及管理员 · 保存 30 天'}</span><h2>平局 · 静态过程示例</h2><p>${state.report==='formal'?'样例已结算：金钱 +120，击杀收益已入账。':'模拟战：不产生正式成长和资产收益。'}</p><p class="muted">预置展示样例，不是前面按钮计算出的战斗。7 名敌方单位用于检验长阵型。</p></div><details open><summary style="padding:12px 0">第 ${state.event+1} 步 · 双方状态（模拟）</summary><div class="desktop-columns"><div><h3>我方</h3>${units()}</div><div><h3>敌方 · 7 名</h3>${units(true)}</div></div></details><h2 style="margin-top:20px">过程 · 24 个记录步骤</h2><p class="muted">步骤不是回合；点“查看此步”同步上方阵型。</p>${events.map((e,i)=>`<details class="log"><summary>${String(i+1).padStart(2,'0')} · ${e}</summary><p>示例：HP 80 → 62（实际减少 18）；SP 40 → 36。${i===0?'开始蓄力，尚未释放技能。':'展示实际行动与变化，不展示整套战术或随机输入。'}</p>${btn('查看此步阵型','event',`data-index="${i}"`)}</details>`).join('')}<div class="actionbar">${btn('回到准备页','page','data-page="adventure"')}</div><details><summary>查看过期 / 清理提示</summary><p class="help">战报详情已过期 / 已由管理员清理。该提示不表示结算被撤销。</p></details>`}
function town(){return `<div class="eyebrow">Town</div><h1>城镇</h1><p class="muted">本轮验证入口位置，以下为摘要样例。</p><div class="stack hub"><details class="card"><summary>交易 · 商店与拍卖</summary><p>暂停新上架时，已有拍卖仍可竞价。</p><p class="help">样例拍品已到期，等待结算。尚不能显示已到账，也不能继续出价。</p></details><details class="card"><summary>世界 Boss · 龙之军团</summary><div class="row">${sprite('mon_013r.gif')}<p>HP 12,800 / 20,000<br>SP 600 / 800（模拟）</p></div><p>正在处理其他挑战，请稍后再试。</p></details><details class="card"><summary>竞技场</summary><p>竞技成员登记后 48 小时才能更换；每场读取最新配置。</p><p>竞技场正在处理挑战，请稍后再试。</p></details><details class="card"><summary>资料 · 图鉴 / 职业 / 物品 / 手册</summary><p>游戏资料与正式定义同源。怪物展示技能、属性与准确掉落概率。</p></details><details class="card"><summary>社区 · 留言 / 意见板 / 公告</summary><p>完成首次建队后可以留言；共用 10 秒发言间隔。</p></details><details class="card"><summary>账号与帮助</summary><p>修改密码 · 恢复码 · 当前设备退出 · 全部设备退出</p><p>会话过期：重新登录后查询原操作，不自动重放旧请求。</p><p>没有角色：仍可打工后重新招募。首次注册：先建队。</p></details></div>`}
function panel(){return state.page==='adventure'?adventure():state.page==='party'?party():state.page==='character'?character():state.page==='report'?report():town()}
function VariantA(){return `${header()}<div class="variant-desc">A · 以出发为主线，准备步骤逐页完成。</div><div class="page"><div class="stepper">${[['party','1 成员'],['character','2 培养'],['adventure','3 出发']].map(([p,n])=>btn(n,'page',`data-page="${p}" class="${state.page===p?'active':''}"`)).join('')}</div>${panel()}</div>${nav()}`}
function VariantB(){return `${header()}<div class="variant-desc">B · 以角色为中心，桌面左列选人，手机顶部切换。</div><div class="workbench">${roster()}<div class="page">${state.page==='adventure'?`<div class="actionbar">${btn('查看当前角色','page','data-page="character" class="primary"')}${btn('出战编队','page','data-page="party"')}</div>`:''}${panel()}</div></div>${nav()}`}
function VariantC(){return `${header()}<div class="variant-desc">C · 信息集中在同一页，按需展开，减少页面跳转。</div><main class="compact"><div class="summary-list">${btn(`编队 ${state.selected.length}/5`,'open','data-open="party"')}${btn('阿岚 · 装备 / 战术','open','data-open="character"')}${btn('准备出战','open','data-open="adventure"')}${btn('历史战报','open','data-open="report"')}</div>${[['adventure','出发与处理状态'],['party','出战成员与阵位'],['character','角色培养'],['report','战报复盘'],['town','城镇与其他入口']].map(([p,n])=>`<details data-section="${p}" ${p===state.page?'open':''}><summary>${n}</summary><div>${p==='adventure'?adventure():p==='party'?party():p==='character'?character():p==='report'?report():town()}</div></details>`).join('')}</main>`}
function globalStatus(){
  const labels={pending:'处理中',unknown:'响应待核对',manual:'待人工处理',cancelled:'已故障取消',done:'已完成'};
  return `<div class="global-status" aria-label="当前操作状态">${[['正式战',state.battle,'formal'],['模拟战',state.simulation,'sim']].filter(([,value])=>labels[value]).map(([name,value,type])=>btn(`${name} · ${labels[value]} →`,value==='done'?'result':'page',value==='done'?`data-type="${type}"`:'data-page="adventure"')).join('')}</div>`;
}
function hybridRoster(){
  return `<aside class="hybrid-roster"><div class="row spread"><h2>选择培养对象</h2>${btn(`出战 ${state.selected.length}/5 ›`,'page','data-page="party"')}</div><label>定位角色<select data-field="edit-character">${state.chars.map((c,i)=>`<option value="${i}" ${i===state.char?'selected':''}>${c[0]} · ${state.selected.includes(i)?'已选出战':'未选出战'}</option>`).join('')}</select></label><p class="muted">共 ${state.chars.length} 名角色 · 横向滑动可查看。点选只切换编辑对象。</p><div class="roster-list">${state.chars.map((c,i)=>btn(`${sprite(c[2])}<span><b>${c[0]}</b><small>${i===state.char?'正在编辑':'点击编辑'}</small><small>${state.selected.includes(i)?'已选出战':'未选出战'} · ${c[3]}</small>${state.plans[i].dirty?'<small class="bad">战术未保存</small>':''}${occupied(i)?'<small>正式战占用中</small>':''}</span>`,'character',`data-char="${i}" aria-pressed="${i===state.char}"`)).join('')}</div></aside>`;
}
function stepState(step){
  return `<p class="muted">第 ${step+1} 步之后 · 独立预置状态样例</p><div class="desktop-columns"><section><h3>我方 · 5 名</h3>${units(false,step)}</section><section><h3>敌方 · 7 名</h3>${units(true,step)}</section></div>`;
}
function hybridReport(){return pagedReport()}
function VariantD(){
  return `<div class="hybrid">${header()}${globalStatus().includes('<button')?`<div class="hybrid-chrome">${globalStatus()}</div>`:''}<div class="variant-desc">D · A＋B 组合 · 分页战报待试用</div>${state.page==='character'?`<div class="hybrid-workbench">${hybridRoster()}<main class="page">${character()}</main></div>`:`<main class="page">${panel()}</main>`}${nav()}</div>`;
}
function render(){document.querySelector('#screen').classList.toggle('hybrid-screen',variant==='D');document.querySelector('#app').innerHTML=({A:VariantA,B:VariantB,C:VariantC,D:VariantD}[variant])();document.querySelector('#variant-label').textContent=`原型 ${variant} · ${names[variant]}`}
function chooseVariant(delta){variant=variants[(variants.indexOf(variant)+delta+variants.length)%variants.length];if(variant==='B'&&state.page==='adventure'&&!busy()&&!pending(state.simulation))state.page='character';const url=new URL(location.href);url.searchParams.set('variant',variant);history.replaceState({},'',url);render()}
function commitAllowed(characterId=state.char){if(scenario()==='pause'){notice('当前维护或保护性暂停，未提交修改。只读信息仍可查看。');return false}if(scenario()==='conflict'){notice('另一页面已修改角色；本页编辑仍保留，请刷新核对后重新确认。');return false}if(occupied(characterId)){notice('角色正在正式出战，处理完成后才能修改。');return false}return true}
function accept(sim=false,test=false){if(test&&!commitAllowed())return;if(scenario()==='pause'||scenario()==='conflict'){notice('尚未受理；配置、记忆队伍与资产均未改变。');return}if(scenario()==='busy'){notice('处理容量已满，未受理；未扣体力，未保存配置或记忆队伍。');return}if(pending(sim?state.simulation:state.battle)){notice(sim?'已有模拟处理中，请查询原操作。':'已有正式战处理中，请查询原操作。');return}if(!test&&(state.selected.length===0||state.selected.length>5)){notice('请选择 1–5 名出战角色。');return}if(!sim&&state.stamina-state.reserved<1){notice('体力不足，未受理。');return}if(test){draft().savedRules=structuredClone(draft().rules);draft().dirty=false;draft().save='战术已保存 · 测试已受理'}else if(state.remember)state.remembered=[...state.selected];state.acceptedConfigs[sim?'sim':'formal']=(test?[state.char]:state.selected).map(i=>({character:i,name:state.chars[i][0],rules:structuredClone(savedBattleRules(i))}));const value=scenario()==='unknown'?'unknown':scenario()==='manual'?'manual':'pending';if(sim)state.simulation=value;else{state.battle=value;state.occupied=[...state.selected];state.reserved=1}state.page='adventure';notice(sim?'模拟已受理，不产生正式收益。':'正式战已受理，预留 1 体力。');render()}
document.querySelector('#app').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,i=Number(b.dataset.index);if(a==='report-step'){openReportStep(i,true);return}if(a==='report-prev'||a==='report-next'){openReportStep(reportReader.step+(a==='report-prev'?-1:1));return}if(a==='report-directory'){returnReportDirectory();return}if(a==='report-type'||a==='result'||(a==='page'&&b.dataset.page==='report'))reportReader.step=null;if(a==='step-state'){const box=b.nextElementSibling;box.hidden=!box.hidden;b.setAttribute('aria-expanded',String(!box.hidden));b.textContent=box.hidden?'展开此步双方状态':'收起此步双方状态';if(!box.hidden&&!box.innerHTML)box.innerHTML=stepState(i);return}if(a==='page'){state.page=b.dataset.page;if(state.page==='character'&&variant!=='D')state.char=0}if(a==='character'){state.char=Number(b.dataset.char);state.page='character'}if(a==='tab')state.tab=b.dataset.tab;if(a==='candidate')state.candidate=i;if(a==='equip'&&commitAllowed()){const old=state.gear;state.gear=state.candidate;state.candidate=old;notice('模拟换装成功，旧装备已回背包。')}if(a==='learn'&&commitAllowed()&&!state.learned){state.learned=true;state.points-=4;notice('模拟学习成功，扣除 4 点。')}if(['up','down'].includes(a)){const j=i+(a==='up'?-1:1);[draft().rules[i],draft().rules[j]]=[draft().rules[j],draft().rules[i]];draft().dirty=true;draft().save='有未保存修改'}if(a==='discard'){draft().rules=structuredClone(draft().savedRules);draft().dirty=false;draft().save='已放弃未保存修改'}if(a==='save'&&commitAllowed()){draft().savedRules=structuredClone(draft().rules);draft().dirty=false;draft().save='战术已保存';notice('模拟保存成功。')}if(a==='swap'&&!draft().dirty&&commitAllowed()){[draft().rules,draft().backup]=[draft().backup,draft().rules];draft().savedRules=structuredClone(draft().rules);draft().save='当前与备用已交换';notice('两套方案已互换。')}if(a==='capacity')draft().capacity=Number(b.dataset.capacity);if(a==='battle'){accept();return}if(a==='simulate'){accept(true);return}if(a==='test'){accept(true,true);return}if(a==='resolve'){const sim=b.dataset.mode==='sim',key=sim?'simulation':'battle';if(state[key]==='unknown'){state[key]='pending';notice('已找到原操作：已受理，正在处理。')}else if(scenario()==='pause')notice('业务停写中，原操作仍保留。');else if(scenario()==='cancel'){state[key]='cancelled';if(!sim){state.reserved=0;state.occupied=[]}notice('故障取消：不扣体力，不发收益，受理时保存的配置与记忆保留。')}else if(state[key]==='manual')notice('仍待管理员处理；不重复出战或释放预留。');else{state[key]='done';if(!sim){state.stamina-=state.reserved;state.reserved=0;state.occupied=[];state.money+=120}state.page='report';reportReader.step=null;state.report=sim?'sim':'formal';notice(sim?'模拟完成，无正式收益。':'正式战结算成功（演示）：体力 -1，金钱 +120。')}}if(a==='result'){state.report=b.dataset.type;state.page='report'}if(a==='report-type')state.report=b.dataset.type;if(a==='event')state.event=i;if(a==='open')state.page=b.dataset.open;render();if(variant==='D'&&['page','character','result'].includes(a))document.querySelector('#screen').scrollIntoView({block:'start'});if(a==='event')document.querySelector('#app h1')?.scrollIntoView({block:'start'});if(a==='open')document.querySelector(`[data-section="${state.page}"]`)?.scrollIntoView({block:'start'})});
document.querySelector('#app').addEventListener('change',e=>{const t=e.target;if(t.dataset.field==='edit-character'){state.char=Number(t.value);state.page='character';render();return}if(t.dataset.member!==undefined){const i=Number(t.dataset.member);if(t.checked&&state.selected.length>=5){t.checked=false;notice('出战最多 5 人，请先取消一名成员。');return}state.selected=t.checked?[...state.selected,i].sort((a,b)=>a-b):state.selected.filter(x=>x!==i);render()}if(t.dataset.position!==undefined){if(commitAllowed(Number(t.dataset.position)))state.chars[Number(t.dataset.position)][3]=t.value;render()}if(t.dataset.field==='remember')state.remember=t.checked;if(t.dataset.rule!==undefined){const r=draft().rules[Number(t.dataset.rule)];r[t.dataset.prop]=t.dataset.prop==='value'?Math.min(100,Math.max(0,Number(t.value))):t.value;draft().dirty=true;draft().save='有未保存修改';render()}});
document.querySelector('#prev').onclick=()=>chooseVariant(-1);document.querySelector('#next').onclick=()=>chooseVariant(1);
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable],button,summary'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();if(variant==='D'&&state.page==='report'&&reportReader.step!==null){openReportStep(reportReader.step+(e.key==='ArrowLeft'?-1:1));return}chooseVariant(e.key==='ArrowLeft'?-1:1)}});
document.querySelector('#width').onchange=e=>{const screen=document.querySelector('#screen');screen.classList.toggle('full',e.target.value==='full');screen.style.setProperty('--preview-width',e.target.value==='full'?'1160px':e.target.value+'px');screen.style.width=e.target.value==='full'?'':e.target.value+'px'};
document.querySelector('#reset').onclick=()=>{state=initial();reportReader.step=null;if(variant==='B')state.page='character';render();notice('模拟数据已重置。')};if(variant==='B')state.page='character';render();

window.addEventListener('beforeunload',e=>{if(state.plans.some(p=>p.dirty)){e.preventDefault();e.returnValue=''}});

document.querySelector('#app').addEventListener('submit',e=>{if(!e.target.matches('.gear-filters'))return;e.preventDefault();state.gearSlot=e.target.querySelector('[data-field=gear-slot]').value;state.gearQuery=e.target.querySelector('[data-field=gear-query]').value;state.candidate=gearCandidates()[0]?.i??null;render()});

document.querySelector('#app').addEventListener('submit',e=>{if(!e.target.matches('.report-jump'))return;e.preventDefault();const input=e.target.querySelector('[name=step]');const value=input.value.trim();const number=Number(value);if(!value||!Number.isInteger(number)||number<1||number>reportSteps.length){document.querySelector('#report-jump-error').textContent=`请输入 1–${reportSteps.length} 的整数步骤号。`;input.focus();return}openReportStep(number-1)});
